- {
    "id": "remanent_magnetization",
    "name": "Remanent magnetization",
    "symbol": "\\\\mathbf M_r",
    "symbol_text": "Mᵣ",
    "units": "\\\\mathrm{A\\\\,m^{-1}}",
    "value_type": "vector",
    "spatial": true,
    "category": "mineral_property",
    "layer": 1,
    "description": "SOURCE_FACT — Magnetization retained independently of the present inducing field; not recoverable from scalar susceptibility alone.",
    "directly_observable": false,
    "references": [
      "astic2020"
    ],
    "modality": [
      "magnetic"
    ]
  }

- {
    "id": "magnetic_anomaly",
    "name": "Total-field magnetic anomaly",
    "symbol": "\\\\Delta T_B",
    "symbol_text": "ΔTᴮ",
    "units": "\\\\mathrm{T}\\\\ (\\\\mathrm{nT\\\\ in\\\\ surveys})",
    "value_type": "vector",
    "spatial": false,
    "category": "observation",
    "layer": 5,
    "description": "SOURCE_FACT — Magnetic field anomaly projected onto the ambient-field direction under the small-anomaly approximation.",
    "directly_observable": true,
    "references": [
      "li1996",
      "astic2020"
    ],
    "modality": [
      "magnetic"
    ]
  }

- {
    "id": "density_contrast",
    "kind": "mass_density",
    "name": "Density contrast",
    "symbol": "\\\\Delta\\\\rho",
    "symbol_text": "Δρ",
    "units": "\\\\mathrm{kg\\\\,m^{-3}}",
    "value_type": "scalar",
    "spatial": true,
    "category": "effective_property",
    "layer": 3,
    "description": "SOURCE_FACT — Density relative to the chosen background; negative contrast is physically permissible.",
    "directly_observable": false,
    "references": [
      "li1998"
    ],
    "modality": [
      "gravity"
    ]
  }

- {
    "id": "reference_density",
    "name": "Background density",
    "symbol": "\\\\rho_{\\\\mathrm{ref}}",
    "symbol_text": "ρref",
    "units": "\\\\mathrm{kg\\\\,m^{-3}}",
    "value_type": "scalar",
    "spatial": true,
    "category": "reservoir_state",
    "layer": 2,
    "description": "SOURCE_FACT — Reference density used to define the anomaly and model contrast; part of processing/model specification.",
    "directly_observable": false,
    "references": [
      "li1998"
    ],
    "modality": [
      "gravity"
    ]
  }

